(()=>{const K='rc_pending_trial_v1';try{const p=JSON.parse(sessionStorage.getItem(K)||localStorage.getItem(K)||'null');if(p&&new URLSearchParams(location.hash.slice(1)).has('access_token'))location.hash='#dj-login'}catch(e){}})();(()=>{const f=window.fetch.bind(window);window.fetch=(i,o={})=>{const u=typeof i==='string'?i:(i&&i.url)||'';if(/\/rest\/v1\/rpc\/dj_get_event_qr(?:\?|$)/.test(u))return Promise.resolve(new Response('""',{status:200,headers:{'content-type':'application/json'}}));return f(i,o)}})();(()=>{const show=()=>{if(document.getElementById('rc-hard-plan'))return;const m=document.createElement('div');m.id='rc-hard-plan';m.style='position:fixed;inset:0;z-index:2147483647;background:rgba(0,0,0,.9);padding:16px;overflow:auto;color:#fff;font:16px Arial';m.innerHTML='<div style="max-width:720px;margin:auto;background:#160d20;border:1px solid #35e6da;border-radius:24px;padding:20px"><div style="display:flex;justify-content:space-between"><h2>Adquirir un plan</h2><button id="rc-hard-close" style="font-size:28px;background:none;border:0;color:white">×</button></div><p>Elige un plan y una forma de pago.</p><b>Métodos de pago</b><div style="display:flex;gap:8px;margin:12px 0"><button data-p="Yape">Yape</button><button data-p="Mercado Pago">Mercado Pago</button><button data-p="PayPal">PayPal</button></div><p id="rc-hard-pay" style="background:white;color:#111;padding:12px;border-radius:8px">Yape seleccionado. Luego sube tu comprobante.</p><div id="rc-hard-plans" style="display:flex;gap:8px;flex-wrap:wrap"></div><p style="color:#35e6da">Subir comprobante</p><input type="file" accept="image/*" style="width:100%"><button id="rc-hard-close2" style="margin-top:16px;width:100%;padding:12px;background:#35e6da;border:0;border-radius:10px">Cerrar</button></div>';document.body.appendChild(m);m.querySelector('#rc-hard-plans').innerHTML=[['15 días','S/. 25.00'],['Mensual','S/. 35.00'],['Anual','S/. 340.00']].map(x=>'<button style="padding:14px;background:#15343a;color:#fff;border:1px solid #35e6da;border-radius:10px">'+x[0]+'<br>'+x[1]+'</button>').join('');m.querySelectorAll('[data-p]').forEach(b=>b.onclick=()=>m.querySelector('#rc-hard-pay').textContent=b.dataset.p+' seleccionado. Continúa con el pago.');m.querySelector('#rc-hard-close').onclick=()=>m.remove();m.querySelector('#rc-hard-close2').onclick=()=>m.remove()};const bind=()=>document.querySelectorAll('button').forEach(b=>{if(/Adquirir\s+un\s+plan/i.test(b.textContent)&&!b.dataset.hardPlan){b.dataset.hardPlan='1';['pointerdown','mousedown','click'].forEach(t=>b.addEventListener(t,e=>{e.preventDefault();e.stopImmediatePropagation();show()},true))}});new MutationObserver(bind).observe(document.documentElement,{childList:true,subtree:true});bind()})()
